/**
 * Opaque base64url continuation, at most 512 characters and 384 decoded bytes. Decode only a versioned (endpoint,created_at,id,normalized scope/status/category filters) tuple; reject malformed, unknown-version, endpoint-mismatched or filter-mismatched cursors with 400 INVALID_SUBSCRIPTION_QUERY. The tuple is a position, never authority; current RLS and filters must be applied before keyset pagination.
 *
 */
export const zSubscriptionCursor = z.string().min(1).max(512).regex(/^[A-Za-z0-9_-]+$/);

/**
 * Default 20; valid integer range 1 through 50, with no clamping.
 */
export const zSubscriptionLimit = z.int().gte(1).lte(50).default(20);

/**
 * Exactly one nonspace printable ASCII key; global burn retained at most24h, duplicates never replay.
 */
export const zWebEnrollmentIdempotencyKey = zWebEnrollmentKey;

/**
 * Exactly one public nonce matched to Origin/chain/binding cookie and operation purpose.
 */
export const zWebEnrollmentBrowserNonce = zWebEnrollmentNonce;

/**
 * Required on every mutating POST; retries cannot replay secrets/proofs or bypass throttles.
 */
export const zIdempotencyKey = z.string().min(16).max(255);

/**
 * Must exactly match a configured allowlisted origin; null, wildcard and reflected credentialed origins are rejected.
 */
export const zExactOrigin = z.url();

/**
 * Required for web-cookie/browser transport; must exactly match configured allowlist. Mobile Bearer transport does not send browser Origin.
 */
export const zOriginForWeb = z.url();

/**
 * Required for web transport only: public nonce paired with the distinct HttpOnly browser binding cookie. Mobile omits it.
 *
 */
export const zBrowserNonce = z.string();

/**
 * Required for web cookie unsafe calls; session-bound, separate from browser nonce. Bearer mobile does not use cookie CSRF.
 */
export const zSessionCsrf = z.string();

/**
 * Required current session CSRF for the verified browser identity and session; separate from browser nonce.
 */
export const zBrowserSessionCsrf = z.string().min(1);

